const versiculos = [
  { texto: "De madrugada faze com que eu ouça tua bondade, porque em ti confio; faze-me saber o caminho que devo seguir, porque a ti levanto minha alma.", referencia: "Salmos 143:8", capitulo: "PSA143" },
  { texto: "E meu Deus suprirá todas a vossas necessidades segundo as suas riquezas em glória em Cristo Jesus.", referencia: "Filipenses 4:19", capitulo: "PHP04" },
  { texto: "Bom é louvar ao SENHOR, e cantar louvores ao teu nome, ó Altíssimo.", referencia: "Salmos 92:1", capitulo: "PSA092" },
  { texto: "Jesus lhe disse: Eu sou o caminho, e a verdade, e a vida. Ninguém vem ao Pai, a não ser por mim.", referencia: "João 14:6", capitulo: "JHN14" },
  { texto: "Louva ao SENHOR, ó minha alma; e que todo o meu interior louve ao seu santo nome.", referencia: "Salmos 103:1", capitulo: "PSA103" },
  { texto: "E farei de ti uma grande nação, e te abençoarei, e engrandecerei o teu nome, e tu serás uma bênção.", referencia: "Gênesis 12:2", capitulo: "GEN12" },
  { texto: "O Deus da esperança vos encha de toda alegria e paz na fé, para que abundeis em esperança no poder do Espírito Santo.", referencia: "Romanos 15:13", capitulo: "ROM15" },
  { texto: "Bem-aventurado aquele que tem o Deus de Jacó como sua ajuda, cuja esperança está no SENHOR seu Deus.", referencia: "Salmos 146:5", capitulo: "PSA146" },
  { texto: "Melhor é o que demora para se irritar do que o valente; e melhor é aquele que domina seu espírito do que aquele que toma uma cidade.", referencia: "Provérbios 16:32", capitulo: "PRO16" },
  { texto: "Grandes coisas o SENHOR fez para nós; por isso estamos alegres.", referencia: "Salmos 126:3", capitulo: "PSA126" },
  { texto: "Pois: “Todo aquele que invocar o nome do Senhor será salvo.”", referencia: "Romanos 10:13", capitulo: "ROM10" },
  { texto: "Assim também será minha palavra, que não voltará a mim vazia; ao contrário, ela fará o que me agrada, e cumprirá aquilo para que a enviei.", referencia: "Isaías 55:11", capitulo: "ISA55" },
  { texto: "O SENHOR é minha força e minha canção, porque ele tem sido minha salvação.", referencia: "Salmos 118:14", capitulo: "PSA118" },
  { texto: "E ele disse: Meu rosto irá contigo, e te farei descansar.", referencia: "Êxodo 33:14", capitulo: "EXO33" },
  { texto: "Cria em mim um coração puro, ó Deus; e renova um espírito firme em meu interior.", referencia: "Salmos 51:10", capitulo: "PSA051" },
  { texto: "Mas Jesus respondeu: Está escrito: Não só de pão viverá o ser humano, mas de toda palavra que sai da boca de Deus.", referencia: "Mateus 4:4", capitulo: "MAT04" },
  { texto: "E em nenhum outro há salvação; porque nenhum outro nome há abaixo do céu, dado entre os seres humanos, em quem devemos ser salvos.", referencia: "Atos 4:12", capitulo: "ACT04" },
  { texto: "Descansa no SENHOR, e espera nele; não te irrites contra aquele cujo caminho prospera, nem com o homem que planeja maldades.", referencia: "Salmos 37:7", capitulo: "PSA037" },
  { texto: "Tudo aguenta, tudo crê, tudo espera, tudo suporta.", referencia: "1 Coríntios 13:7", capitulo: "1CO13" },
  { texto: "Deus é nosso refúgio e força; socorro oportuno nas angústias.", referencia: "Salmos 46:1", capitulo: "PSA046" },
  { texto: "Eu sei que tudo podes, e nenhum de teus pensamentos pode ser impedido.", referencia: "Jó 42:2", capitulo: "JOB42" },
  { texto: "Porque o SENHOR Deus é sol e escudo; o SENHOR concederá graça e honra; ele não negará o bem aos que andam em integridade.", referencia: "Salmos 84:11", capitulo: "PSA084" },
  { texto: "E Jesus lhes disse: Eu sou o pão da vida; quem vem a mim de maneira nenhuma terá fome, e quem crê em mim nunca terá sede.", referencia: "João 6:35", capitulo: "JHN06" },
  { texto: "Aquele que mora no esconderijo do Altíssimo, à sombra do Todo-Poderoso habitará.", referencia: "Salmos 91:1", capitulo: "PSA091" },
  { texto: "Pois nós fomos feitos por ele, criados em Cristo Jesus para as boas obras, que Deus preparou para que nelas andássemos.", referencia: "Efésios 2:10", capitulo: "EPH02" },
  { texto: "Entrega o teu caminho ao SENHOR; confia nele, e ele agirá.", referencia: "Salmos 37:5", capitulo: "PSA037" },
  { texto: "O SENHOR é bom, é fortaleza no dia da angústia; ele conhece os que nele confiam.", referencia: "Naum 1:7", capitulo: "NAM01" },
  { texto: "Louvarei a ti, SENHOR com todo o meu coração; contarei todas as tuas maravilhas.", referencia: "Salmos 9:1", capitulo: "PSA009" },
  { texto: "Confia no SENHOR com todo o teu coração; e não te apoies em teu próprio entendimento.", referencia: "Provérbios 3:5", capitulo: "PRO03" },
  { texto: "Tu és meu refúgio e meu escudo; eu espero em tua palavra.", referencia: "Salmos 119:114", capitulo: "PSA119" },
  { texto: "Lançando sobre ele toda a vossa ansiedade; porque ele tem cuidado de vós.", referencia: "1 Pedro 5:7", capitulo: "1PE05" },
  { texto: "Sede fortes, e ele fortalecerá vosso coração, todos vós que esperais no SENHOR.", referencia: "Salmos 31:24", capitulo: "PSA031" },
  { texto: "Benditos são os limpos de coração, porque eles verão a Deus.", referencia: "Mateus 5:8", capitulo: "MAT05" },
  { texto: "Não a nós, SENHOR; não a nós, mas a teu nome dá glória; por tua bondade, por tua fidelidade.", referencia: "Salmos 115:1", capitulo: "PSA115" },
  { texto: "Porque eu, o SENHOR teu Deus, te seguro pela tua mão direita, e te digo: Não temas; eu te ajudo.", referencia: "Isaías 41:13", capitulo: "ISA41" },
  { texto: "Se o SENHOR não estiver edificando a casa, em vão trabalham nela seus construtores; se o SENHOR não estiver guardando a cidade, em vão o guarda vigia.", referencia: "Salmos 127:1", capitulo: "PSA127" },
  { texto: "Pois Deus não nos deu espírito de medo; mas sim de força, de amor, e de moderação.", referencia: "2 Timóteo 1:7", capitulo: "2TI01" },
  { texto: "Direi ao SENHOR: Tu és meu refúgio e minha fortaleza; Deus meu, em quem confio.", referencia: "Salmos 91:2", capitulo: "PSA091" },
  { texto: "Há muitos pensamentos no coração do homem; porém o conselho do SENHOR prevalecerá.", referencia: "Provérbios 19:21", capitulo: "PRO19" },
  { texto: "Porque o SENHOR é bom, sua bondade dura para sempre; e a fidelidade dele continua de geração após geração.", referencia: "Salmos 100:5", capitulo: "PSA100" },
  { texto: "Não estejais ansiosos por coisa alguma; mas em tudo, por meio de orações e súplicas com ações de gratidão, sejam os vossos pedidos conhecidos por Deus.", referencia: "Filipenses 4:6", capitulo: "PHP04" },
  { texto: "Ao SENHOR pertence a terra, e sua plenitude; o mundo, e os que nele habitam.", referencia: "Salmos 24:1", capitulo: "PSA024" },
  { texto: "Se algum de vós tem falta de sabedoria, peça a Deus, que concede generosamente a todos sem repreender, e lhe será dada.", referencia: "Tiago 1:5", capitulo: "JAS01" },
  { texto: "Porém não cansemos de fazer o bem, pois no tempo devido colheremos, se não desistirmos.", referencia: "Gálatas 6:9", capitulo: "GAL06" },
  { texto: "Eu te louvarei porque de um jeito assombroso e maravilhoso eu fui feito; maravilhosas são tuas obras; e minha alma sabe muito bem.", referencia: "Salmos 139:14", capitulo: "PSA139" },
  { texto: "Mas em todas estas coisas somos mais que vencedores, por meio daquele que nos amou.", referencia: "Romanos 8:37", capitulo: "ROM08" },
  { texto: "O SENHOR está comigo, não temerei; o que poderá me fazer o homem?", referencia: "Salmos 118:6", capitulo: "PSA118" },
  { texto: "Então, que diremos acerca dessas coisas? Se Deus é por nós, quem será contra nós?", referencia: "Romanos 8:31", capitulo: "ROM08" },
  { texto: "Ficai quietos, e sabei que eu sou Deus; eu serei exaltado entre as nações; serei exaltado sobre a terra.", referencia: "Salmos 46:10", capitulo: "PSA046" },
  { texto: "O nome do SENHOR é uma torre forte; o justo correrá até ele, e ficará seguro.", referencia: "Provérbios 18:10", capitulo: "PRO18" },
  { texto: "Mas ele me disse: “Minha graça te basta, porque meu poder se aperfeiçoa na fraqueza”. Por isso, com muito prazer, eu me orgulharei nas minhas fraquezas, para que o poder de Cristo habite em mim.", referencia: "2 Coríntios 12:9", capitulo: "2CO12" },
  { texto: "Porém tu, SENHOR, és escudo para mim; minha glória, e o que levanta minha cabeça.", referencia: "Salmos 3:3", capitulo: "PSA003" },
  { texto: "Amados, nos amemos uns aos outros; porque o amor é de Deus, e todo aquele que ama é nascido de Deus e conhece a Deus.", referencia: "1 João 4:7", capitulo: "1JN04" },
  { texto: "O SENHOR apareceu a mim já há muito tempo, dizendo: Com amor eterno eu tenho te amado; por isso com bondade te sustento.", referencia: "Jeremias 31:3", capitulo: "JER31" },
  { texto: "Este é o dia em que o SENHOR agiu; alegremos e enchamos de alegria nele.", referencia: "Salmos 118:24", capitulo: "PSA118" },
  { texto: "De tudo o que foi ouvido, a conclusão é: teme a Deus, e guarda os mandamentos dele; porque isto é o dever de todo homem.", referencia: "Eclesiastes 12:13", capitulo: "ECC12" },
  { texto: "Espera no SENHOR, esforça-te, e ele fortalecerá o teu coração; espera pois ao SENHOR.", referencia: "Salmos 27:14", capitulo: "PSA027" },
  { texto: "E conhecereis a verdade, e a verdade vos libertará.", referencia: "João 8:32", capitulo: "JHN08" },
  { texto: "Bem-aventurada é a nação em que seu Deus é o SENHOR; o povo que ele escolheu para si por herança.", referencia: "Salmos 33:12", capitulo: "PSA033" },
  { texto: "Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.", referencia: "Gálatas 6:2", capitulo: "GAL06" },
  { texto: "Cantai ao SENHOR uma nova canção; cantai ao SENHOR toda a terra.", referencia: "Salmos 96:1", capitulo: "PSA096" },
  { texto: "Benditos são os mansos, porque eles herdarão a terra.", referencia: "Mateus 5:5", capitulo: "MAT05" },
  { texto: "Muita paz têm aqueles que amam a tua lei; e para eles não há tropeço.", referencia: "Salmos 119:165", capitulo: "PSA119" },
  { texto: "Ora, a fé é a certeza das coisas que se esperam, e a prova das coisas que não se veem.", referencia: "Hebreus 11:1", capitulo: "HEB11" },
  { texto: "Vede quão grande amor o Pai tem nos dado, que fôssemos chamados filhos de Deus. Por isso o mundo não nos conhece, pois não conhece a ele.", referencia: "1 João 3:1", capitulo: "1JN03" },
  { texto: "Ele não temerá o mau rumor; o seu coração está firme, confiante no SENHOR.", referencia: "Salmos 112:7", capitulo: "PSA112" },
  { texto: "Pois assim diz o Senhor DEUS, o Santo de Israel: Com arrependimento e descanso, ficaríeis livres; com calma e confiança teríeis força; mas vós não quisestes.", referencia: "Isaías 30:15", capitulo: "ISA30" },
  { texto: "Assim como um pai se compadece dos filhos, assim também o SENHOR se compadece daqueles que o temem.", referencia: "Salmos 103:13", capitulo: "PSA103" },
  { texto: "Porque Deus não mandou seu Filho ao mundo para que condenasse ao mundo; mas sim para que o mundo por ele fosse salvo.", referencia: "João 3:17", capitulo: "JHN03" },
  { texto: "Os céus declaram a glória de Deus; e o firmamento anuncia a obra de suas mãos.", referencia: "Salmos 19:1", capitulo: "PSA019" },
  { texto: "Glória nas alturas a Deus, paz na terra, e aos seres humanos boa vontade.", referencia: "Lucas 2:14", capitulo: "LUK02" },
  { texto: "Confiai, povo, nele em todo o tempo; derramai vosso coração diante dele; Deus é nosso refúgio.", referencia: "Salmos 62:8", capitulo: "PSA062" },
  { texto: "Trazei todos os dízimos à casa do tesouro, para que haja alimento em minha casa; e provai-me nisto, diz o SENHOR dos exércitos, se não vos abrir as janelas dos céu, e derramar sobre vós bênção transbordante.", referencia: "Malaquias 3:10", capitulo: "MAL03" },
  { texto: "O SENHOR é a minha força e meu escudo; meu coração confiou nele, e foi socorrido; por isso meu coração salta de alegria; e com meu canto eu o louvarei.", referencia: "Salmos 28:7", capitulo: "PSA028" },
  { texto: "E o SENHOR é o que vai diante de ti; ele será contigo, não te deixará, nem te desamparará; não temas, nem te intimides.", referencia: "Deuteronômio 31:8", capitulo: "DEU31" },
  { texto: "Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões.", referencia: "Salmos 103:12", capitulo: "PSA103" },
  { texto: "Para todas as coisas há um tempo determinado, e todo propósito abaixo do céu tem seu tempo.", referencia: "Eclesiastes 3:1", capitulo: "ECC03" },
  { texto: "No dia em que eu tiver medo, eu confiarei em ti.", referencia: "Salmos 56:3", capitulo: "PSA056" },
  { texto: "Faça resplandecer o SENHOR seu rosto sobre ti, e tenha de ti misericórdia.", referencia: "Números 6:25", capitulo: "NUM06" },
  { texto: "Ensina -nos a contar nossos dias de tal maneira que alcancemos um coração sábio.", referencia: "Salmos 90:12", capitulo: "PSA090" },
  { texto: "Honra ao SENHOR com teus bens, e com a primeira parte de toda a tua renda.", referencia: "Provérbios 3:9", capitulo: "PRO03" },
  { texto: "Mas grande lucro é a devoção divina acompanhada de contentamento.", referencia: "1 Timóteo 6:6", capitulo: "1TI06" },
  { texto: "Porém ele foi ferido por nossas transgressões, e esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos curados.", referencia: "Isaías 53:5", capitulo: "ISA53" },
  { texto: "Vede como é bom e agradável que irmãos convivam em união!", referencia: "Salmos 133:1", capitulo: "PSA133" },
  { texto: "E Deus limpará toda lágrima dos olhos deles; e não haverá mais morte, nem pranto, nem clamor, nem mais haverá dor; porque as primeiras coisas já passaram.”", referencia: "Apocalipse 21:4", capitulo: "REV21" },
  { texto: "E vos darei um novo coração, e porei um novo espírito dentro de vós; e tirarei de vossa carne o coração de pedra, e vos darei um coração de carne.", referencia: "Ezequiel 36:26", capitulo: "EZK36" },
  { texto: "Sejam agradáveis as palavras de minha boca, e o pensamento do meu coração, diante de ti, ó SENHOR, minha rocha e meu Libertador.", referencia: "Salmos 19:14", capitulo: "PSA019" },
  { texto: "Clama a mim, e eu te responderei; e te direi coisas grandes e difíceis que tu não conheces.", referencia: "Jeremias 33:3", capitulo: "JER33" },
  { texto: "Nossa alma espera no SENHOR; ele é nossa socorro e nosso escudo.", referencia: "Salmos 33:20", capitulo: "PSA033" },
  { texto: "O coração alegre anima o rosto, mas pela dor do coração o espírito se abate.", referencia: "Provérbios 15:13", capitulo: "PRO15" },
  { texto: "Em vez disso, sede benignos uns com os outros, misericordiosos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.", referencia: "Efésios 4:32", capitulo: "EPH04" },
  { texto: "Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores.", referencia: "Salmos 1:1", capitulo: "PSA001" },
  { texto: "Pode, por acaso, uma mulher se esquecer do filho que ainda amamenta, de modo que não se compadeça do filho de seu próprio ventre? Ainda que elas se esquecessem, contudo, eu não me esquecerei de ti.", referencia: "Isaías 49:15", capitulo: "ISA49" },
  { texto: "A resposta suave desvia o furor, mas a palavra pesada faz a ira aumentar.", referencia: "Provérbios 15:1", capitulo: "PRO15" },
  { texto: "Tudo ele fez belo ao seu tempo; também pôs a sensação de eternidade no coração deles, sem que o homem consiga entender a obra que Deus fez, desde o princípio até o fim.", referencia: "Eclesiastes 3:11", capitulo: "ECC03" },
  { texto: "Porque montes se removerão e morros se retirarão, porém minha bondade não se removerá de ti, nem o pacto de minha paz se retirará, diz o SENHOR, que tem compaixão de ti.", referencia: "Isaías 54:10", capitulo: "ISA54" },
  { texto: "Assim como a corça geme de desejo pelas correntes de águas, assim também minha alma geme de desejo por ti, Deus.", referencia: "Salmos 42:1", capitulo: "PSA042" },
  { texto: "O eterno Deus é o teu refúgio, e abaixo os braços eternos; ele expulsará de diante de ti o inimigo, e dirá: Destrói.", referencia: "Deuteronômio 33:27", capitulo: "DEU33" },
  { texto: "Mas vós sois a geração escolhida, o sacerdócio real, a nação santa, o povo adquirido; a fim de que anuncieis as virtudes daquele que vos chamou das trevas para a sua maravilhosa luz.", referencia: "1 Pedro 2:9", capitulo: "1PE02" },
  { texto: "Experimentai, e vede que o SENHOR é bom; bem-aventurado é o homem que confia nele.", referencia: "Salmos 34:8", capitulo: "PSA034" },
  { texto: "E não vos conformeis com a presente era; mas transformai-vos pela renovação da vossa mentalidade, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus.", referencia: "Romanos 12:2", capitulo: "ROM12" },
  { texto: "Mas, acima de tudo, tende fervoroso amor uns para com os outros; porque o amor cobrirá uma multidão de pecados.", referencia: "1 Pedro 4:8", capitulo: "1PE04" },
  { texto: "O homem que tem amigos pode ser prejudicado por eles; porém há um amigo mais chegado que um irmão.", referencia: "Provérbios 18:24", capitulo: "PRO18" },
  { texto: "O SENHOR guardará tua saída e tua entrada, desde agora e para sempre.", referencia: "Salmos 121:8", capitulo: "PSA121" },
  { texto: "Benditos são os que choram, porque eles serão consolados.", referencia: "Mateus 5:4", capitulo: "MAT05" },
  { texto: "Piedoso e misericordioso é o SENHOR; ele demora para se irar, e tem grande bondade.", referencia: "Salmos 145:8", capitulo: "PSA145" },
  { texto: "Vinde a mim todos vós que estais cansados e sobrecarregados, e eu vos farei descansar.", referencia: "Mateus 11:28", capitulo: "MAT11" },
  { texto: "O ladrão não vem, senão para roubar, matar, e destruir; eu vim para que tenham vida, e a tenham em abundância.", referencia: "João 10:10", capitulo: "JHN10" },
  { texto: "Tomai sobre vós o meu jugo e aprendei de mim, porque sou manso e humilde de coração; e encontrareis descanso para as vossas almas.", referencia: "Mateus 11:29", capitulo: "MAT11" },
  { texto: "A morte e a vida estão no poder da língua; e aquele que a ama comerá do fruto dela.", referencia: "Provérbios 18:21", capitulo: "PRO18" },
  { texto: "Porém agora, SENHOR, tu és nosso Pai; nós somos barro, e tu és nosso oleiro; e todos nós somos obra de tuas mãos.", referencia: "Isaías 64:8", capitulo: "ISA64" },
  { texto: "Procurai ao SENHOR e à sua força; buscai a sua face continuamente.", referencia: "1 Crônicas 16:11", capitulo: "1CH16" },
  { texto: "Confia tuas obras ao SENHOR, e teus pensamentos serão firmados.", referencia: "Provérbios 16:3", capitulo: "PRO16" },
  { texto: "Nisto todos conhecerão que sois meus discípulos: se vós tiverdes amor uns aos outros.", referencia: "João 13:35", capitulo: "JHN13" },
  { texto: "Ensinando-lhes a guardar todas as coisas que eu vos tenho mandado. E eis que eu estou convosco todos os dias, até o fim dos tempos. Amém.", referencia: "Mateus 28:20", capitulo: "MAT28" },
  { texto: "E eles lhe disseram: Crê no Senhor Jesus Cristo, e serás salvo, tu e a tua casa.", referencia: "Atos 16:31", capitulo: "ACT16" },
  { texto: "O SENHOR levante a ti seu rosto, e ponha em ti paz.", referencia: "Números 6:26", capitulo: "NUM06" },
  { texto: "É preferível ter um bom nome do que muitas riquezas; e ser favorecido é melhor que a prata e o o ouro.", referencia: "Provérbios 22:1", capitulo: "PRO22" },
  { texto: "O SENHOR dará força a seu povo; o SENHOR abençoará a seu povo com paz.", referencia: "Salmos 29:11", capitulo: "PSA029" },
  { texto: "Se vós estiverdes em mim, e minhas palavras estiverem em vós, tudo o que quiserdes pedireis, e será feito para vós.", referencia: "João 15:7", capitulo: "JHN15" },
  { texto: "Porque sua ira dura por um momento; mas seu favor dura por toda a vida; o choro fica pela noite, mas a alegria vem pela manhã.", referencia: "Salmos 30:5", capitulo: "PSA030" },
  { texto: "Ora, sem fé é impossível agradar a Deus. Pois é necessário que aquele que se aproxima de Deus creia que ele existe, e que ele é recompensador dos que o buscam.", referencia: "Hebreus 11:6", capitulo: "HEB11" },
  { texto: "Sujeitai-vos, pois, a Deus; resisti ao diabo, e ele fugirá de vós.", referencia: "Tiago 4:7", capitulo: "JAS04" },
  { texto: "Portanto eu vos digo que tudo o que pedirdes orando, crede que recebereis, e vós o tereis.", referencia: "Marcos 11:24", capitulo: "MRK11" },
  { texto: "Falou-lhes pois Jesus outra vez, dizendo: Eu sou a luz do mundo; quem me seguir não andará em trevas, mas terá luz de vida.", referencia: "João 8:12", capitulo: "JHN08" },
  { texto: "Porque ele ordenou aos anjos quanto a ti, para que guardem todos os teus caminhos.", referencia: "Salmos 91:11", capitulo: "PSA091" },
  { texto: "E o SENHOR respondeu a Samuel: Não olhes à sua aparência, nem à sua grande estatura, porque eu o rejeito; porque o SENHOR olha não o que o homem olha; pois que o homem olha o que está diante de seus olhos, mas o SENHOR olha o coração.", referencia: "1 Samuel 16:7", capitulo: "1SA16" },
  { texto: "Ah DEUS, nosso Senhor, quão glorioso é o teu nome sobre toda a terra! Pois tu puseste tua majestade acima dos céus.", referencia: "Salmos 8:1", capitulo: "PSA008" },
  { texto: "Não há santo como o SENHOR: Porque não há ninguém além de ti; E não há refúgio como o nosso Deus.", referencia: "1 Samuel 2:2", capitulo: "1SA02" },
  { texto: "Rasgai vosso coração, e não vossas vestes.Convertei-vos ao SENHOR vosso Deus, porque ele é piedoso e misericordioso, que demora para se irar, e é grande em bondade, e que se arrepende de castigar.", referencia: "Joel 2:13", capitulo: "JOL02" },
  { texto: "Portanto, meus amados irmãos, toda pessoa seja pronta para ouvir, tardia para falar, tardia para se irar.", referencia: "Tiago 1:19", capitulo: "JAS01" },
  { texto: "O temor ao SENHOR é o principio do conhecimento; os tolos desprezam a sabedoria e a instrução.", referencia: "Provérbios 1:7", capitulo: "PRO01" },
  { texto: "Tu me fazes conhecer os teus caminhos; ensina-me teus lugares onde se deve andar.", referencia: "Salmos 25:4", capitulo: "PSA025" },
  { texto: "Porque um menino nos nasceu, um filho nos foi dado; e o governo está sobre seus ombros; e seu nome se chama Maravilhoso, Conselheiro, Deus Forte, Pai da Eternidade, Príncipe da Paz.", referencia: "Isaías 9:6", capitulo: "ISA09" },
  { texto: "Portanto, se alguém está em Cristo, uma nova criatura é; as coisas velhas já passaram, eis que tudo se fez novo.", referencia: "2 Coríntios 5:17", capitulo: "2CO05" },
  { texto: "Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto.", referencia: "Mateus 7:7", capitulo: "MAT07" },
  { texto: "O SENHOR é meu pastor, nada me faltará.", referencia: "Salmos 23:1", capitulo: "PSA023" },
  { texto: "Benditos são os que têm fome e sede de justiça, porque eles serão saciados.", referencia: "Mateus 5:6", capitulo: "MAT05" },
  { texto: "O SENHOR te abençoe, e te guarde.", referencia: "Números 6:24", capitulo: "NUM06" },
  { texto: "Portanto, agora que somos justificados pela fé, temos paz com Deus por meio do nosso Senhor Jesus Cristo.", referencia: "Romanos 5:1", capitulo: "ROM05" },
  { texto: "O coração alegre é um bom remédio, mas o espírito abatido faz os ossos se secarem.", referencia: "Provérbios 17:22", capitulo: "PRO17" },
  { texto: "Mas vós recebereis poder do Espírito Santo, que virá sobre vós; e vós sereis minhas testemunhas, tanto em Jerusalém como em toda a Judeia, e Samaria, e até ao último lugar da terra.", referencia: "Atos 1:8", capitulo: "ACT01" },
  { texto: "E disto tenho certeza: aquele que começou a boa obra em vós irá completá-la até o dia de Jesus Cristo.", referencia: "Filipenses 1:6", capitulo: "PHP01" },
  { texto: "Lutei a boa luta, terminei a carreira, guardei a fé.", referencia: "2 Timóteo 4:7", capitulo: "2TI04" },
  { texto: "Vinde, cantemos alegres ao SENHOR; gritemos de alegria à rocha de nossa salvação.", referencia: "Salmos 95:1", capitulo: "PSA095" },
  { texto: "Eu sou o Alfa e o Ômega, o principio e o fim, o primeiro e o último.”", referencia: "Apocalipse 22:13", capitulo: "REV22" },
  { texto: "Portanto, meus amados irmãos, sede firmes, imóveis e sempre abundantes na obra do Senhor, sabendo que o vosso trabalho não é vão no Senhor.", referencia: "1 Coríntios 15:58", capitulo: "1CO15" },
  { texto: "Ah Senhor DEUS! Eis que tu fizeste os céus e a terra com teu grande poder, e com teu braço estendido; não há coisa alguma que seja difícil para ti.", referencia: "Jeremias 32:17", capitulo: "JER32" },
  { texto: "Benditos são os pacíficos, porque eles serão chamados filhos de Deus.", referencia: "Mateus 5:9", capitulo: "MAT05" },
  { texto: "Alguns confiam em carruagens, e outros em cavalos; mas nós nos lembraremos do nome do SENHOR nosso Deus.", referencia: "Salmos 20:7", capitulo: "PSA020" },
  { texto: "Instrui ao menino em seu caminho, e até quando envelhecer, não se desviará dele.", referencia: "Provérbios 22:6", capitulo: "PRO22" },
  { texto: "O SENHOR está perto de todos os que o chamam; de todos os que clamam a ele sinceramente.", referencia: "Salmos 145:18", capitulo: "PSA145" },
  { texto: "Nada façais por rivalidade egoísta ou por vanglória; ao contrário, por humildade cada um considere o outro superior a si mesmo.", referencia: "Filipenses 2:3", capitulo: "PHP02" },
  { texto: "Porque o SENHOR conhece o caminho dos justos; porém o caminho dos maus perecerá.", referencia: "Salmos 1:6", capitulo: "PSA001" },
  { texto: "Alegrai-vos na esperança. Sede pacientes na aflição. Perseverai na oração.", referencia: "Romanos 12:12", capitulo: "ROM12" },
  { texto: "Eu sou a videira, vós sois os ramos; quem está em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer.", referencia: "João 15:5", capitulo: "JHN15" },
  { texto: "Bendito seja o Senhor; dia após dia ele nos carrega; Deus é nossa salvação.", referencia: "Salmos 68:19", capitulo: "PSA068" },
  { texto: "E tudo quanto fizerdes, fazei de coração, como para o Senhor, e não para as pessoas.", referencia: "Colossenses 3:23", capitulo: "COL03" },
  { texto: "Quem é Deus como tu, que perdoa a maldade, e ignora a transgressão do restante de sua herança? Ele não retém para sempre sua ira, porque ele tem prazer na bondade.", referencia: "Miqueias 7:18", capitulo: "MIC07" },
  { texto: "A alma generosa prosperará, e aquele que saciar também será saciado.", referencia: "Provérbios 11:25", capitulo: "PRO11" },
  { texto: "Ele dá força ao cansado, e multiplica as forças daquele que não tem vigor.", referencia: "Isaías 40:29", capitulo: "ISA40" },
  { texto: "O SENHOR é minha força, e minha canção, E foi-me por salvação: Este é meu Deus, e a este engrandecerei; Deus de meu pai, e a este exaltarei.", referencia: "Êxodo 15:2", capitulo: "EXO15" },
  { texto: "Louva ao SENHOR, ó minha alma; e não te esqueças de nenhum dos benefícios dele.", referencia: "Salmos 103:2", capitulo: "PSA103" },
  { texto: "E disse-lhes mais: Ide, comei gorduras, e bebei doçuras, e enviai porções aos que não têm preparado; porque este é um dia consagrado ao nosso Senhor; portanto não vos entristeçais, porque a alegria do SENHOR é vossa força.", referencia: "Neemias 8:10", capitulo: "NEH08" },
  { texto: "Esforçai-vos e tende ânimo; não temais, nem tenhais medo deles: que o SENHOR teu Deus é o que vai contigo: não te deixará nem te desamparará.", referencia: "Deuteronômio 31:6", capitulo: "DEU31" },
  { texto: "E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses aos quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos amorreus em cuja terra habitais: que eu e minha casa serviremos ao SENHOR.", referencia: "Josué 24:15", capitulo: "JOS24" },
  { texto: "E o SENHOR te guiará continuamente, fartará a tua alma mesmo em grandes secas, e fortalecerá teus ossos; e tu serás como um jardim regado, como um manancial de águas, cujas águas nunca faltam.", referencia: "Isaías 58:11", capitulo: "ISA58" },
  { texto: "Pois eu sei que meu Redentor vive, e ao fim se levantará sobre a terra.", referencia: "Jó 19:25", capitulo: "JOB19" },
  { texto: "E disse-lhes: Ide por todo o mundo, pregai o Evangelho a toda criatura.", referencia: "Marcos 16:15", capitulo: "MRK16" },
  { texto: "Desde o nascer do sol até o poente, seja louvado o nome do SENHOR.", referencia: "Salmos 113:3", capitulo: "PSA113" },
  { texto: "E Jesus lhe respondeu: Amarás ao Senhor teu Deus com todo o teu coração, com toda a tua alma, e com todo o teu entendimento.", referencia: "Mateus 22:37", capitulo: "MAT22" },
  { texto: "Porque não me envergonho do Evangelho de Cristo, pois é o poder de Deus para a salvação de todo aquele que crê, primeiramente do judeu, e também do grego.", referencia: "Romanos 1:16", capitulo: "ROM01" },
  { texto: "Ponho ao SENHOR continuamente diante de mim; porque ele está à minha direita; nunca serei abalado.", referencia: "Salmos 16:8", capitulo: "PSA016" },
  { texto: "Quando passares pelas águas, estarei contigo; e ao passares pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chamas arderão em ti.", referencia: "Isaías 43:2", capitulo: "ISA43" },
  { texto: "E como vós quereis que as pessoas vos façam, fazei-lhes vós também da mesma maneira.", referencia: "Lucas 6:31", capitulo: "LUK06" },
  { texto: "Mas fiel é o Senhor, que vos fortalecerá e vos guardará do maligno.", referencia: "2 Tessalonicenses 3:3", capitulo: "2TH03" },
  { texto: "Minha carne e meu coração desfalecem; porém Deus será a rocha do meu coração e minha porção para sempre.", referencia: "Salmos 73:26", capitulo: "PSA073" },
  { texto: "Suportai-vos uns aos outros, e perdoai-vos uns aos outros, se alguém tiver queixa contra outro. Como Cristo vos perdoou, assim também fazei.", referencia: "Colossenses 3:13", capitulo: "COL03" },
  { texto: "Não andeis, pois, ansiosos pelo dia de amanhã, porque o amanhã cuidará de si mesmo. Basta a cada dia o seu mal.", referencia: "Mateus 6:34", capitulo: "MAT06" },
  { texto: "O SENHOR é minha rocha, e minha fortaleza, e meu libertador, meu Deus, meu rochedo, em quem confio; é meu escudo, e a força da minha salvação, meu alto refúgio.", referencia: "Salmos 18:2", capitulo: "PSA018" },
  { texto: "Não sejais, pois, semelhantes a eles; porque vosso Pai sabe o que necessitais, antes que vós peçais a ele.", referencia: "Mateus 6:8", capitulo: "MAT06" },
  { texto: "Levanto meus olhos aos montes. De onde virá meu socorro?", referencia: "Salmos 121:1", capitulo: "PSA121" },
  { texto: "E nós conhecemos e cremos no amor que Deus tem por nós. Deus é amor, e quem está no amor está em Deus, e Deus nele.", referencia: "1 João 4:16", capitulo: "1JN04" },
  { texto: "Certamente minha alma se aquieta por causa de Deus; dele vem minha salvação.", referencia: "Salmos 62:1", capitulo: "PSA062" },
  { texto: "O ódio desperta brigas; mas o amor cobre todas as transgressões.", referencia: "Provérbios 10:12", capitulo: "PRO10" },
  { texto: "Porque eu sei os pensamentos que penso quanto a vós, diz o SENHOR, pensamentos de paz, e não de mal, para vos dar um futuro com esperança.", referencia: "Jeremias 29:11", capitulo: "JER29" },
  { texto: "Dois são melhores do que um, porque eles têm melhor recompensa por seu trabalho.", referencia: "Eclesiastes 4:9", capitulo: "ECC04" },
  { texto: "Eu deitarei, e dormirei em paz; porque só tu, SENHOR, me fazes descansar seguro.", referencia: "Salmos 4:8", capitulo: "PSA004" },
  { texto: "Pois, se com a tua boca declarares que Jesus é Senhor, e em teu coração creres que Deus o ressuscitou dos mortos, serás salvo.", referencia: "Romanos 10:9", capitulo: "ROM10" },
  { texto: "Ele sara aos de coração partido, e os cura de suas dores.", referencia: "Salmos 147:3", capitulo: "PSA147" },
  { texto: "E eu vos digo: pedi, e será vos dado; buscai, e achareis; batei, e vos será aberto.", referencia: "Lucas 11:9", capitulo: "LUK11" },
  { texto: "Mas buscai primeiramente o Reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.", referencia: "Mateus 6:33", capitulo: "MAT06" },
  { texto: "SENHOR, pela manhã ouvirás minha voz; pela manhã apresentarei meu clamor a ti, e ficarei esperando.", referencia: "Salmos 5:3", capitulo: "PSA005" },
  { texto: "Cada qual faça como propõe em seu coração, não com tristeza, ou por obrigação; porque Deus ama ao que dá com alegria.", referencia: "2 Coríntios 9:7", capitulo: "2CO09" },
  { texto: "Mas Deus prova o seu amor por nós através de Cristo haver morrido por nós, quando ainda éramos pecadores.", referencia: "Romanos 5:8", capitulo: "ROM05" },
  { texto: "Dá reconhecimento a ele em todas os teus caminhos; e ele endireitará tuas veredas.", referencia: "Provérbios 3:6", capitulo: "PRO03" },
  { texto: "Benditos são os humildes de espírito, porque deles é o Reino dos céus.", referencia: "Mateus 5:3", capitulo: "MAT05" },
  { texto: "Orai sem cessar.", referencia: "1 Tessalonicenses 5:17", capitulo: "1TH05" },
  { texto: "Amo o SENHOR, porque ele escuta minha voz e minhas súplicas.", referencia: "Salmos 116:1", capitulo: "PSA116" },
  { texto: "Buscai ao SENHOR enquanto se pode achar; invocai-o enquanto ele está perto.", referencia: "Isaías 55:6", capitulo: "ISA55" },
  { texto: "Pois tu, Senhor, és bom, perdoador, e grande em bondade para todos os que clamam a ti.", referencia: "Salmos 86:5", capitulo: "PSA086" },
  { texto: "E o Deus de toda graça, que nos chamou para a sua eterna glória em Cristo Jesus, depois de sofrerdes um pouco, ele vos aperfeiçoe, confirme, fortifique, e estabeleça fundamento.", referencia: "1 Pedro 5:10", capitulo: "1PE05" },
  { texto: "Toda a Escritura é divinamente inspirada e proveitosa para ensinar, para mostrar erros, para corrigir, e para instruir na justiça.", referencia: "2 Timóteo 3:16", capitulo: "2TI03" },
  { texto: "Misericordioso e piedoso é o SENHOR, que demora para se irar, e é grande em bondade.", referencia: "Salmos 103:8", capitulo: "PSA103" },
  { texto: "Amai-vos cordialmente uns aos outros com amor de irmãos, preferindo honrar uns aos outros.", referencia: "Romanos 12:10", capitulo: "ROM12" },
  { texto: "E ele falou comigo, dizendo: Esta é palavra do SENHOR a Zorobabel, que diz: Não se fará por força, nem por violência, mas sim por meu espírito, diz o SENHOR dos exércitos.", referencia: "Zacarias 4:6", capitulo: "ZEC04" },
  { texto: "Pois meus pensamentos não são vossos pensamentos, nem vossos caminhos são meus caminhos, diz o SENHOR.", referencia: "Isaías 55:8", capitulo: "ISA55" },
  { texto: "E aquela Palavra se fez carne, e habitou entre nós; (e vimos sua glória, como glória do unigênito do Pai) cheio de graça e de verdade.", referencia: "João 1:14", capitulo: "JHN01" },
  { texto: "Dai, e será vos dado; medida boa, comprimida, sacudida e transbordante vos darão no vosso colo; pois com a mesma medida que medirdes vos medirão de volta.", referencia: "Lucas 6:38", capitulo: "LUK06" },
  { texto: "Portanto, acheguemo-nos com confiança ao trono da graça, para que possamos receber misericórdia e encontrar graça para sermos socorridos no tempo adequado.", referencia: "Hebreus 4:16", capitulo: "HEB04" },
  { texto: "Deus não é homem, para que minta; nem filho de homem para que se arrependa: ele disse, e não fará?; Falou, e não o executará?", referencia: "Números 23:19", capitulo: "NUM23" },
  { texto: "E a paz de Deus, para a qual também fostes chamados em um só corpo, governe em vossos corações, e sede gratos.", referencia: "Colossenses 3:15", capitulo: "COL03" },
  { texto: "Mas sim, que tem seu prazer na Lei do SENHOR; e medita em sua Lei de dia e de noite.", referencia: "Salmos 1:2", capitulo: "PSA001" },
  { texto: "Agradecei em tudo, pois essa é a vontade de Deus em Cristo Jesus para vós mesmos.", referencia: "1 Tessalonicenses 5:18", capitulo: "1TH05" },
  { texto: "Aproximai-vos de Deus, e ele se aproximará de vós. Limpai as vossas mãos, pecadores, e vós de dupla mentalidade, purificai os vossos corações.", referencia: "Tiago 4:8", capitulo: "JAS04" },
  { texto: "Porque pela graça sois salvos, por meio da fé; e isto não vem de vós; é dom de Deus.", referencia: "Efésios 2:8", capitulo: "EPH02" },
  { texto: "Eis que Deus é minha salvação; nele confiarei, e não terei medo; porque minha força e minha canção é o SENHOR DEUS; e ele tem sido minha salvação.", referencia: "Isaías 12:2", capitulo: "ISA12" },
  { texto: "O caminho de Deus é perfeito; a palavra do SENHOR é purificada, é escudo é de todos os que nele confiam.", referencia: "2 Samuel 22:31", capitulo: "2SA22" },
  { texto: "Pois que proveito há para alguém, se ganhar o mundo todo, mas perder a sua alma? Ou que dará alguém em resgate da sua alma?", referencia: "Mateus 16:26", capitulo: "MAT16" },
  { texto: "O amigo ama em todo tempo, e o irmão nasce para ajudar na angústia.", referencia: "Provérbios 17:17", capitulo: "PRO17" },
  { texto: "Eis que eu estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei até ele, e cearei com ele, e ele comigo.", referencia: "Apocalipse 3:20", capitulo: "REV03" },
  { texto: "Mas crescei em graça e conhecimento de nosso Senhor e Salvador Jesus Cristo. A ele seja a glória, tanto agora como no dia da eternidade, Amém!", referencia: "2 Pedro 3:18", capitulo: "2PE03" },
  { texto: "No princípio criou Deus os céus e a terra.", referencia: "Gênesis 1:1", capitulo: "GEN01" },
  { texto: "Celebrai a o SENHOR, porque é bom; Porque sua misericórdia é eterna.", referencia: "1 Crônicas 16:34", capitulo: "1CH16" },
  { texto: "E eis que eu estou contigo, e te guardarei por onde quer que fores, e te farei voltar a esta terra; porque não te deixarei, até que eu tenha feito o que te disse.”", referencia: "Gênesis 28:15", capitulo: "GEN28" },
  { texto: "Eu sou o bom Pastor; o bom Pastor dá sua vida pelas ovelhas.", referencia: "João 10:11", capitulo: "JHN10" },
  { texto: "E confiarão em ti os que conhecem o teu nome; porque tu, SENHOR, nunca desamparaste aos que te buscam.", referencia: "Salmos 9:10", capitulo: "PSA009" },
  { texto: "Bendito é o homem que suporta a provação; pois, quando for aprovado, receberá a coroa da vida, que o Senhor prometeu aos que o amam.", referencia: "Tiago 1:12", capitulo: "JAS01" },
  { texto: "Mas graças a Deus, que nos dá vitória por meio do nosso Senhor Jesus Cristo.", referencia: "1 Coríntios 15:57", capitulo: "1CO15" },
  { texto: "DEUS, o Senhor, é minha fortaleza; ele fará meus pés como os das corças, e me fará andar sobre meus lugares altos.(Para o regente, com instrumentos de cordas).", referencia: "Habacuque 3:19", capitulo: "HAB03" },
  { texto: "Guia-me em tua verdade, e ensina-me; porque tu és o Deus de minha salvação; eu espero por ti o dia todo.", referencia: "Salmos 25:5", capitulo: "PSA025" },
  { texto: "Se se humilhar meu povo, sobre os quais nem nome é invocado, e orarem, e buscarem meu rosto, e se converterem de seus maus caminhos; então eu ouvirei desde os céus, e perdoarei seus pecados, e sararei sua terra.", referencia: "2 Crônicas 7:14", capitulo: "2CH07" },
  { texto: "Agradecei ao SENHOR, porque ele é bom; porque sua bondade dura para sempre.", referencia: "Salmos 107:1", capitulo: "PSA107" },
  { texto: "Acima de tudo o que se deve guardar, guarda o teu coração; porque dele procedem as saídas da vida.", referencia: "Provérbios 4:23", capitulo: "PRO04" },
  { texto: "E ele disse: As coisas que são impossíveis para os seres humanos são possíveis para Deus.", referencia: "Lucas 18:27", capitulo: "LUK18" },
  { texto: "Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus; porque eu ainda o louvarei; ele é a minha salvação e o meu Deus.", referencia: "Salmos 42:11", capitulo: "PSA042" },
  { texto: "Eis que farei uma coisa nova, agora surgirá; por acaso não a reconhecereis? Pois porei um caminho no deserto, e rios na terra vazia.", referencia: "Isaías 43:19", capitulo: "ISA43" },
  { texto: "E sabemos que todas as coisas juntamente contribuem para o bem daqueles que amam a Deus, dos que são chamados segundo o seu propósito.", referencia: "Romanos 8:28", capitulo: "ROM08" },
  { texto: "O Senhor não é tardio em sua promessa (como alguns a consideram tardia); mas ele é paciente para conosco, não querendo que alguns pereçam, mas sim que todos venham ao arrependimento.", referencia: "2 Pedro 3:9", capitulo: "2PE03" },
  { texto: "Pensai nas coisas de cima, não nas que estão na terra.", referencia: "Colossenses 3:2", capitulo: "COL03" },
  { texto: "Pois vós, irmãos, fostes chamados para a liberdade. Somente não useis a liberdade como oportunidade para a carne; em vez disso, servi-vos uns aos outros pelo amor.", referencia: "Gálatas 5:13", capitulo: "GAL05" },
  { texto: "O SENHOR te guardará de todo mal; ele guardará a tua alma.", referencia: "Salmos 121:7", capitulo: "PSA121" },
  { texto: "No restante, meus irmãos, tudo o que é verdadeiro, tudo o que é respeitável, tudo o que é justo, tudo o que é puro, tudo o que é amável, tudo o que é de boa fama, se há alguma virtude, e se há algo digno de elogio, nisto pensai.", referencia: "Filipenses 4:8", capitulo: "PHP04" },
  { texto: "Portanto, a fé vem pelo ouvir, e o ouvir pela palavra de Deus.", referencia: "Romanos 10:17", capitulo: "ROM10" },
  { texto: "O SENHOR fará por completo o que ele tem para mim; ó SENHOR, tua bondade dura para sempre; não abandones as obras de tuas mãos.", referencia: "Salmos 138:8", capitulo: "PSA138" },
  { texto: "Meus filhinhos, amemos não de palavra, nem de língua, mas sim com ação e verdade.", referencia: "1 João 3:18", capitulo: "1JN03" },
  { texto: "A ansiedade no coração do homem o abate; mas uma boa palavra o alegra.", referencia: "Provérbios 12:25", capitulo: "PRO12" },
  { texto: "O amor é paciente, é bondoso; o amor não é invejoso; o amor não é orgulhoso, não é arrogante.", referencia: "1 Coríntios 13:4", capitulo: "1CO13" },
  { texto: "Benditos são os misericordiosos, porque eles alcançarão misericórdia.", referencia: "Mateus 5:7", capitulo: "MAT05" },
  { texto: "Elas são novas a cada manhã; grande é a tua fidelidade.", referencia: "Lamentações 3:23", capitulo: "LAM03" },
  { texto: "Bendito o homem que confia no SENHOR, cuja confiança é o SENHOR.", referencia: "Jeremias 17:7", capitulo: "JER17" },
  { texto: "Mantenho esperança no SENHOR, a minha alma espera; e persisto em sua palavra.", referencia: "Salmos 130:5", capitulo: "PSA130" },
  { texto: "O Senhor é o Espírito; e onde está o Espírito do Senhor, aí há liberdade.", referencia: "2 Coríntios 3:17", capitulo: "2CO03" },
  { texto: "Porque onde estiver o vosso tesouro, ali estará também o vosso coração.", referencia: "Mateus 6:21", capitulo: "MAT06" },
  { texto: "Pois, para mim, o viver é Cristo, e o morrer é lucro.", referencia: "Filipenses 1:21", capitulo: "PHP01" },
  { texto: "Todas as vossas coisas sejam feitas em amor.", referencia: "1 Coríntios 16:14", capitulo: "1CO16" },
  { texto: "Mas os que confiam no SENHOR renovarão as forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão.", referencia: "Isaías 40:31", capitulo: "ISA40" },
  { texto: "O temor do homem arma ciladas; mas o que confia no senhor ficará em segurança.", referencia: "Provérbios 29:25", capitulo: "PRO29" },
  { texto: "Olha que te mando que te esforces e sejas valente: não temas nem desmaies, porque o SENHOR teu Deus será contigo onde quer que fores.", referencia: "Josué 1:9", capitulo: "JOS01" },
  { texto: "Porém, olhando Jesus para eles, disse: Para os seres humanos, é impossível; mas para Deus, não; porque para Deus tudo é possível.", referencia: "Marcos 10:27", capitulo: "MRK10" },
  { texto: "Este é meu mandamento: que vos ameis uns aos outros, assim como eu vos amei.", referencia: "João 15:12", capitulo: "JHN15" },
  { texto: "E agrada-te no SENHOR; e ele te dará os pedidos de teu coração.", referencia: "Salmos 37:4", capitulo: "PSA037" },
  { texto: "Não se perturbe vosso coração; credes em Deus, crede também em mim.", referencia: "João 14:1", capitulo: "JHN14" },
  { texto: "O coração em paz é vida para o corpo, mas a inveja é como podridão nos ossos.", referencia: "Provérbios 14:30", capitulo: "PRO14" },
  { texto: "Guardei a tua palavra em meu coração, para eu não pecar contra ti.", referencia: "Salmos 119:11", capitulo: "PSA119" },
  { texto: "Bom é o SENHOR para os que nele esperam, para a alma que o busca.", referencia: "Lamentações 3:25", capitulo: "LAM03" },
  { texto: "Se me amais, guardai meus mandamentos.", referencia: "João 14:15", capitulo: "JHN14" },
  { texto: "Alegrai-vos sempre.", referencia: "1 Tessalonicenses 5:16", capitulo: "1TH05" },
  { texto: "Deus, tu és meu Deus. Eu te busco ao amanhecer; minha alma tem sede de ti, minha carne muito te deseja, em terra seca, cansativa, sem águas.", referencia: "Salmos 63:1", capitulo: "PSA063" },
  { texto: "O livro desta lei nunca se apartará de tua boca: antes de dia e de noite meditarás nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem.", referencia: "Josué 1:8", capitulo: "JOS01" },
  { texto: "Vós pensastes mal sobre mim, mas Deus o encaminhou para o bem, para fazer o que vemos hoje, para manter em vida muito povo.", referencia: "Gênesis 50:20", capitulo: "GEN50" },
  { texto: "O coração do homem planeja seu caminho, mas é o SENHOR que dirige seus passos.", referencia: "Provérbios 16:9", capitulo: "PRO16" },
  { texto: "Deus é Espírito, e os que o adoram devem adorá -lo em espírito e em verdade.", referencia: "João 4:24", capitulo: "JHN04" },
  { texto: "Nun:Tua palavra é lâmpada para meus pés e luz para meu caminho.", referencia: "Salmos 119:105", capitulo: "PSA119" },
  { texto: "E Jesus lhe disse: Se podes crer, tudo é possível ao que crê.", referencia: "Marcos 9:23", capitulo: "MRK09" },
  { texto: "Porque, se vivemos, para o Senhor vivemos; e se morremos, para o Senhor morremos. Portanto, quer vivamos, quer morramos, do Senhor somos.", referencia: "Romanos 14:8", capitulo: "ROM14" },
  { texto: "Alegrai-vos sempre no Senhor. Volto a dizer: alegrai-vos.", referencia: "Filipenses 4:4", capitulo: "PHP04" },
  { texto: "Estas coisas tenho vos dito para que tenhais paz em mim; no mundo tereis aflição; mas tende bom ânimo; eu venci o mundo.", referencia: "João 16:33", capitulo: "JHN16" },
  { texto: "Tu guardarás em completa paz aquele que tem firme entendimento, pois ele confia em ti.", referencia: "Isaías 26:3", capitulo: "ISA26" },
  { texto: "Porém tu, quando orares, entra em teu quarto, fecha tua porta, e ora a teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público.", referencia: "Mateus 6:6", capitulo: "MAT06" },
  { texto: "A vossa maneira de viver seja sem ganância, contentando-vos com as coisas que tendes. Pois ele disse: Não te deixarei, nem te desampararei.", referencia: "Hebreus 13:5", capitulo: "HEB13" },
  { texto: "Não sejas vencido pelo mal, mas vence o mal com o bem.", referencia: "Romanos 12:21", capitulo: "ROM12" },
  { texto: "Se confessarmos nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.", referencia: "1 João 1:9", capitulo: "1JN01" },
  { texto: "E a luz brilha nas trevas; e as trevas não a compreenderam.", referencia: "João 1:5", capitulo: "JHN01" },
  { texto: "O SENHOR está perto daqueles que estão com o coração partido, e sava os aflitos de espírito.", referencia: "Salmos 34:18", capitulo: "PSA034" },
  { texto: "Força e glória são suas roupas, e ela sorri pelo seu futuro.", referencia: "Provérbios 31:25", capitulo: "PRO31" },
  { texto: "Um novo mandamento vos dou: que vos ameis uns aos outros; tal como eu vos amei, também ameis vós uns aos outros.", referencia: "João 13:34", capitulo: "JHN13" },
  { texto: "Portanto exortai-vos uns aos outros, e edificai-vos uns aos outros, como já fazeis.", referencia: "1 Tessalonicenses 5:11", capitulo: "1TH05" },
  { texto: "Quem crê em mim, como diz a Escritura, rios de água viva correrão do interior de seu corpo.", referencia: "João 7:38", capitulo: "JHN07" },
  { texto: "O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão.", referencia: "Mateus 24:35", capitulo: "MAT24" },
  { texto: "Nós o amamos, porque ele nos amou primeiro.", referencia: "1 João 4:19", capitulo: "1JN04" },
  { texto: "Portanto, agora, nenhuma condenação há para os que estão em Cristo Jesus, que não andam segundo a carne, mas sim segundo o Espírito.", referencia: "Romanos 8:1", capitulo: "ROM08" },
  { texto: "Porque os olhos do SENHOR contemplam toda a terra, para corroborar aos que têm coração íntegro com ele. Loucamente fizeste nisso; porque de agora em diante haverá guerra contra ti.", referencia: "2 Crônicas 16:9", capitulo: "2CH16" },
  { texto: "Esperei com esperança no SENHOR, e ele se inclinou a mim, e ouviu o meu clamor.", referencia: "Salmos 40:1", capitulo: "PSA040" },
  { texto: "No amor não há medo; pelo contrário, o perfeito amor expulsa o medo; pois o medo está relacionado ao castigo; e o que teme não está aperfeiçoado em amor.", referencia: "1 João 4:18", capitulo: "1JN04" },
  { texto: "Por isso nós não prestamos atenção para as coisas visíveis, mas sim para as invisíveis; porque as coisas visíveis são temporárias, mas as invisíveis são eternas.", referencia: "2 Coríntios 4:18", capitulo: "2CO04" },
  { texto: "Aquele que não ama não conhece a Deus, porque Deus é amor.", referencia: "1 João 4:8", capitulo: "1JN04" },
  { texto: "E a esperança não frustra, porque o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.", referencia: "Romanos 5:5", capitulo: "ROM05" },
  { texto: "E esta é a confiança que diante dele: que se pedirmos alguma coisa conforme a sua vontade, ele nos ouve.", referencia: "1 João 5:14", capitulo: "1JN05" },
  { texto: "Disse-lhe Jesus: Eu sou a ressurreição, e a vida; quem crê em mim, ainda que esteja morto, viverá.", referencia: "João 11:25", capitulo: "JHN11" },
  { texto: "E agora continuam a fé, a esperança, e o amor, estes três; porém o maior destes é o amor.", referencia: "1 Coríntios 13:13", capitulo: "1CO13" },
  { texto: "Filhinhos, vós sois de Deus, e tendes vencido esses; pois maior é o que está em vós do que o que está no mundo.", referencia: "1 João 4:4", capitulo: "1JN04" },
  { texto: "No temor ao SENHOR há forte confiança; e será refúgio para seus filhos.", referencia: "Provérbios 14:26", capitulo: "PRO14" },
  { texto: "Pois considero que as aflições deste tempo presente nem se comparam com a glória que nos será revelada.", referencia: "Romanos 8:18", capitulo: "ROM08" },
  { texto: "Jesus Cristo é o mesmo ontem, hoje, e eternamente.", referencia: "Hebreus 13:8", capitulo: "HEB13" },
  { texto: "Toda boa dádiva e todo dom perfeito vem do alto, e desce do Pai das luzes, em quem não há mudança nem sombra de variação.", referencia: "Tiago 1:17", capitulo: "JAS01" },
  { texto: "E será que todo aquele que chamar ao nome do Senhor será salvo.", referencia: "Atos 2:21", capitulo: "ACT02" },
  { texto: "Jesus olhou para eles,e lhes respondeu: Para os seres humanos, isto é impossível; mas para Deus tudo é possível.", referencia: "Mateus 19:26", capitulo: "MAT19" },
  { texto: "Louvarei ao SENHOR em todo tempo; haverá louvor a ele continuamente em minha boca.", referencia: "Salmos 34:1", capitulo: "PSA034" },
  { texto: "Ninguém tem maior amor que este: que alguém ponha sua vida por seus amigos.", referencia: "João 15:13", capitulo: "JHN15" },
  { texto: "Porém, assim como está escrito: “As coisas que o olho não viu, e não subiram que ao coração humano, são as que Deus preparou para os que o amam”.", referencia: "1 Coríntios 2:9", capitulo: "1CO02" },
  { texto: "Já estou crucificado com Cristo. Estou vivendo não mais eu, mas Cristo vive em mim; e vivo a minha vida na carne por meio da fé no Filho de Deus, que me amou, e entregou a si mesmo por mim.", referencia: "Gálatas 2:20", capitulo: "GAL02" },
  { texto: "Assim brilhe vossa luz diante das pessoas, para que vejam vossas boas obras, e glorifiquem ao vosso Pai, que está nos céus.", referencia: "Mateus 5:16", capitulo: "MAT05" },
  { texto: "Certamente o bem e a bondade me seguirão todos os dias de minha vida; e habitarei na casa do SENHOR por muitos e muitos dias.", referencia: "Salmos 23:6", capitulo: "PSA023" },
  { texto: "Pois onde dois ou três estiverem reunidos em meu nome, ali eu estou no meio deles.", referencia: "Mateus 18:20", capitulo: "MAT18" },
  { texto: "Porque Deus amou ao mundo de tal maneira, que deu o seu Filho unigênito; para que todo aquele que nele crê não pereça, mas tenha a vida eterna.", referencia: "João 3:16", capitulo: "JHN03" },
  { texto: "Conheçamos, e prossigamos em conhecer ao SENHOR; sua vinda está preparada como o nascer do sol; ele virá a nós como a chuva, como a chuva da primavera, que rega a terra.", referencia: "Oseias 6:3", capitulo: "HOS06" },
  { texto: "Ele já declarou a ti, ó ser humano, o que é bom; e que mais o SENHOR pede de ti, a não ser fazer o que é justo, amar a bondade, e andar humildemente com teu Deus?", referencia: "Miqueias 6:8", capitulo: "MIC06" },
  { texto: "E Amarás ao SENHOR teu Deus de todo teu coração, e de toda tua alma, e com todo tua poder.", referencia: "Deuteronômio 6:5", capitulo: "DEU06" },
  { texto: "Confiai no SENHOR para sempre, pois no SENHOR DEUS está a rocha eterna.", referencia: "Isaías 26:4", capitulo: "ISA26" },
  { texto: "(Pois andamos pela fé, e não pela vista).", referencia: "2 Coríntios 5:7", capitulo: "2CO05" },
  { texto: "Entrega tuas preocupações ao SENHOR, e ele te sustentará; ele não permitirá que o justo fique caído para sempre.", referencia: "Salmos 55:22", capitulo: "PSA055" },
  { texto: "Mas a todos quantos o receberam, deu-lhes poder de serem feitos filhos de Deus: aos que creem em seu nome.", referencia: "João 1:12", capitulo: "JHN01" },
  { texto: "Confessai as vossas culpas uns aos outros, e orai uns pelos outros, para que sejais curados. A oração de um justo muito pode efetuar.", referencia: "Tiago 5:16", capitulo: "JAS05" },
  { texto: "Toda palavra de Deus é pura; é escudo para os que nele confiam.", referencia: "Provérbios 30:5", capitulo: "PRO30" },
  { texto: "Porque dele, por ele, e para ele, são todas as coisas! A ele seja a glória eternamente! Amém!", referencia: "Romanos 11:36", capitulo: "ROM11" },
  { texto: "Portanto, ao comer, ou ao beber, ou ao fazer qualquer coisa, fazei tudo para a glória de Deus.", referencia: "1 Coríntios 10:31", capitulo: "1CO10" },
  { texto: "Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam.", referencia: "Salmos 23:4", capitulo: "PSA023" },
  { texto: "Levanta-te! Brilha! Porque já chegou a tua luz; e a glória do SENHOR já está raiando sobre ti.", referencia: "Isaías 60:1", capitulo: "ISA60" },
  { texto: "Tu me farás conhecer o caminho da vida; fartura de alegrias há em tua presença; agrados estão em tua mão direita para sempre.", referencia: "Salmos 16:11", capitulo: "PSA016" },
  { texto: "Ninguém despreze a tua juventude, mas sê exemplo aos crentes, na palavra, no comportamento, no amor, em espírito, na fé, e na pureza.", referencia: "1 Timóteo 4:12", capitulo: "1TI04" },
  { texto: "Amado, eu desejo que estejas bem em todas as coisas, e que tenhas saúde, assim como bem está a tua alma.", referencia: "3 João 1:2", capitulo: "3JN01" },
  { texto: "O SENHOR está no meio de ti, guerreiro que salva; ele terá prazer em ti com alegria; ele te aquietará em seu amor, se encherá de alegria por causa de ti com júbilo.", referencia: "Sofonias 3:17", capitulo: "ZEP03" },
  { texto: "É pelas bondades do SENHOR que não somos consumidos, porque suas misericórdias não têm fim.", referencia: "Lamentações 3:22", capitulo: "LAM03" },
  { texto: "E vós me buscareis e achareis, quando me buscardes de todo o vosso coração.", referencia: "Jeremias 29:13", capitulo: "JER29" },
  { texto: "O temor ao SENHOR é o princípio da sabedoria; e o conhecimento dos santos é a prudência.", referencia: "Provérbios 9:10", capitulo: "PRO09" },
  { texto: "Vós sois a luz do mundo; não se pode esconder uma cidade fundada sobre o monte.", referencia: "Mateus 5:14", capitulo: "MAT05" },
  { texto: "Meu socorro vem do SENHOR, que fez os céus e a terra.", referencia: "Salmos 121:2", capitulo: "PSA121" },
  { texto: "A erva se seca, as flores caem; porém a palavra do nosso Deus continua firme para sempre.", referencia: "Isaías 40:8", capitulo: "ISA40" },
  { texto: "O mundo passa, e também a sua cobiça; mas aquele que faz a vontade de Deus permanece para sempre.", referencia: "1 João 2:17", capitulo: "1JN02" },
  { texto: "O SENHOR lutará por vós, e vós ficai quietos.", referencia: "Êxodo 14:14", capitulo: "EXO14" },
  { texto: "Porque aonde estiver vosso tesouro, ali estará também vosso coração.", referencia: "Lucas 12:34", capitulo: "LUK12" },
  { texto: "O SENHOR é minha luz e minha salvação; a quem temerei? O SENHOR é a força da minha vida; de quem terei medo?", referencia: "Salmos 27:1", capitulo: "PSA027" },
  { texto: "O ferro é afiado com ferro; assim também o homem afia o rosto de seu amigo.", referencia: "Provérbios 27:17", capitulo: "PRO27" },
  { texto: "Eu te instruirei, e te ensinarei o caminho que deves seguir; eu te aconselharei, e porei meus olhos em ti.", referencia: "Salmos 32:8", capitulo: "PSA032" },
  { texto: "Portanto tudo o que quiserdes que os outros vos façam, fazei-lhes vós também assim; porque esta é a Lei e os Profetas.", referencia: "Mateus 7:12", capitulo: "MAT07" },
  { texto: "Posso todas as coisas em Cristo que me fortalece.", referencia: "Filipenses 4:13", capitulo: "PHP04" },
  { texto: "E criou Deus o ser humano à sua imagem, à imagem de Deus o criou; macho e fêmea os criou.", referencia: "Gênesis 1:27", capitulo: "GEN01" },
  { texto: "Tudo quanto tem fôlego, louve ao SENHOR! Aleluia!", referencia: "Salmos 150:6", capitulo: "PSA150" },
  { texto: "Pois para Deus nada será impossível.", referencia: "Lucas 1:37", capitulo: "LUK01" },
  { texto: "Estai, pois, firmes na liberdade com que Cristo nos libertou, e não volteis a vos prender com o jugo da escravidão.", referencia: "Gálatas 5:1", capitulo: "GAL05" },
  { texto: "A paz vos deixo, minha paz vos dou; vou dá-la a vós, não como o mundo a dá. Não se perturbe vosso coração, nem se atemorize.", referencia: "João 14:27", capitulo: "JHN14" },
  { texto: "O amor não faz mal ao próximo. Assim, o cumprimento da Lei é o amor.", referencia: "Romanos 13:10", capitulo: "ROM13" },
  { texto: "Por isso não desfalecemos; mas ainda que nosso ser exterior se destrua, todavia o interior se renova a cada dia.", referencia: "2 Coríntios 4:16", capitulo: "2CO04" },
  { texto: "E Jesus lhes respondeu: Por causa da vossa incredulidade; pois em verdade vos digo, que se tivésseis fé como um grão de mostarda, diríeis a este monte: “Passa-te daqui para lá”, E ele passaria. E nada vos seria impossível.", referencia: "Mateus 17:20", capitulo: "MAT17" },
  { texto: "Nenhuma tentação vos veio, que não fosse humana; porém Deus é fiel; que não vos deixará tentar mais do que o que podeis, antes com a tentação também dará a saída, para que a possais suportar.", referencia: "1 Coríntios 10:13", capitulo: "1CO10" },
  { texto: "E acima de tudo isto, revesti-vos do amor, que é o vínculo da perfeição.", referencia: "Colossenses 3:14", capitulo: "COL03" },
  { texto: "Por fim, meus irmãos, fortalecei-vos no Senhor e na força do seu poder.", referencia: "Efésios 6:10", capitulo: "EPH06" },
  { texto: "Agradecei ao SENHOR, porque ele é bom, porque sua bondade dura para sempre.", referencia: "Salmos 136:1", capitulo: "PSA136" },
  { texto: "No princípio era a Palavra, e a Palavra estava junto de Deus, e a Palavra era Deus.", referencia: "João 1:1", capitulo: "JHN01" },
  { texto: "Porque a palavra de Deus é viva e eficaz, e mais afiada do que toda espada de dois gumes, e que penetra até a divisão da alma e do espírito, das juntas e das medulas, e é apta para julgar os pensamentos e intenções do coração.", referencia: "Hebreus 4:12", capitulo: "HEB04" },
  { texto: "Em tudo eu vos tenho mostrado que trabalhando assim, é necessário dar suporte aos enfermos; e lembrar-se das palavras do Senhor Jesus, que disse: Mais bem-aventurado é dar do que receber.", referencia: "Atos 20:35", capitulo: "ACT20" },
  { texto: "Disse-lhe Jesus: Porque me viste, Tomé, creste; bem-aventurados aqueles que não virem, e crerem.", referencia: "João 20:29", capitulo: "JHN20" },
  { texto: "Não temas, porque eu estou contigo; não te assombres, porque eu sou teu Deus. Eu te fortaleço, te ajudo, e te sustento com a minha mão direita de justiça.", referencia: "Isaías 41:10", capitulo: "ISA41" },
  { texto: "Busquei ao SENHOR. Ele me respondeu, e me livrou de todos os meus temores.", referencia: "Salmos 34:4", capitulo: "PSA034" },
];
